SELECT cs.canonical_smiles, cr.compound_name AS substrate_compound_name, md.pref_name AS parent_compound_name, met.met_conversion, met.pathway_key FROM metabolism met JOIN compound_records cr ON met.substrate_record_id = cr.record_id JOIN compound_structures cs ON cr.molregno = cs.molregno LEFT JOIN molecule_hierarchy mh ON cr.molregno = mh.molregno LEFT JOIN molecule_dictionary md ON mh.parent_molregno = md.molregno LIMIT 200
